27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line_1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line_2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
58	            message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    public String getTitle() {
92	        return this.title;
93	    }
94	
95	    public void setTitle(String title) {
96	        this.title = title;
97	    }
98	
99	    public String getAddress() {
100	        return this.address;
101	    }
102	
103	    public void setAddress(String address) {
104	        this.address = address;
105	    }
106	
107	    public String getAddressLine1() {
108	        return this.addressLine1;
109	    }
110	
111	    public void setAddressLine1(String addressLine1) {
112	        this.addressLine1 = addressLine1;
113	    }
114	
115	    public String getAddressLine2() {
116	        return this.addressLine2;
117	    }
118	
119	    public void setAddressLine2(String addressLine2) {
120	        this.addressLine2 = addressLine2;
121	    }
122	
123	    public String getCity() {
124	        return this.city;
125	    }
126	
127	    public void setCity(String city) {
128	        this.city = city;
129	    }
130	
131	    public String getTelephone() {
132	        return this.telephone;
133	    }
134	
135	    public void setTelephone(String telephone) {
136	        this.telephone = telephone;
137	    }
138	
139	    public String getEmail() {
140	        return this.email;
141	    }
142	
143	    public void setEmail(String email) {
144	        this.email = email;
145	    }
146	
147	    public String getPostcode() {
148	        return this.postcode;
149	    }
150	
151	    public void setPostcode(String postcode) {
152	        this.postcode = postcode;
153	    }
154	
155	    public LocalDate getRegistrationDate() {
156	        return this.registrationDate;
157	    }
158	
159	    public void setRegistrationDate(LocalDate registrationDate) {
160	        this.registrationDate = registrationDate;
161	    }
162	
163	    public LocalDate getBirthDate() {
164	        return this.birthDate;
165	    }
166	
167	    public void setBirthDate(LocalDate birthDate) {
168	        this.birthDate = birthDate;
169	    }
170	
171	    public String getCustomerCode() {
172	        return this.customerCode;
173	    }
174	
175	    public void setCustomerCode(String customerCode) {
176	        this.customerCode = customerCode;
177	    }
178	
179	    public String getHouseholdId() {
180	        return this.householdId;
181	    }
182	
183	    public void setHouseholdId(String householdId) {
184	        this.householdId = householdId;
185	    }
186	
187	    public Integer getNamesakeCount() {
188	        return this.namesakeCount;
189	    }
190	
191	    public void setNamesakeCount(Integer namesakeCount) {
192	        this.namesakeCount = namesakeCount;
193	    }
194	
195	    public Boolean getPossibleDuplicate() {
196	        return this.possibleDuplicate;
197	    }
198	
199	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
200	        this.possibleDuplicate = possibleDuplicate;
201	    }
202	
203	    public Integer getPossibleDuplicateOf() {
204	        return this.possibleDuplicateOf;
205	    }
206	
207	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
208	        this.possibleDuplicateOf = possibleDuplicateOf;
209	    }
210	
211	    protected Set<Pet> getPetsInternal() {
212	        if (this.pets == null) {
213	            this.pets = new HashSet<>();
214	        }
215	        return this.pets;
216	    }
217	
218	    protected void setPetsInternal(Set<Pet> pets) {
219	        this.pets = pets;
220	    }
221	
222	    public List<Pet> getPets() {
223	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
224	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
225	        return Collections.unmodifiableList(sortedPets);
226	    }
227	
228	    public void setPets(List<Pet> pets) {
229	        this.pets = new HashSet<>(pets);
230	    }
231	
232	    public void addPet(Pet pet) {
233	        getPetsInternal().add(pet);
234	        pet.setOwner(this);
235	    }
236	
237	    /**
238	     * Return the Pet with the given name, or null if none found for this Owner.
239	     *
240	     * @param name to test
241	     * @return true if pet name is already in use
242	     */
243	    public Pet getPet(String name) {
244	        return getPet(name, false);
245	    }
246	
247	    /**
248	     * Return the Pet with the given name, or null if none found for this Owner.
249	     *
250	     * @param name to test
251	     * @return true if pet name is already in use
252	     */
253	    public Pet getPet(String name, boolean ignoreNew) {
254	        name = name.toLowerCase();
255	        for (Pet pet : getPetsInternal()) {
256	            if (!ignoreNew || !pet.isNew()) {
257	                String compName = pet.getName();
258	                compName = compName.toLowerCase();
259	                if (compName.equals(name)) {
260	                    return pet;
261	                }
262	            }
263	        }
264	        return null;
265	    }
266	
267	    public Pet getPet(Integer petId) {
268	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
269	    }
270	
271	    @Override
272	    public String toString() {
273	        return new ToStringCreator(this)
274	
275	            .append("id", this.getId())
276	            .append("new", this.isNew())
277	            .append("lastName", this.getLastName())
278	            .append("firstName", this.getFirstName())
279	            .append("address", this.address)
280	            .append("city", this.city)
281	            .append("telephone", this.telephone)
282	            .toString();
283	    }
284	}
