1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import jakarta.validation.Valid;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
14	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
15	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
16	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
17	import org.springframework.validation.annotation.Validated;
18	import org.springframework.web.bind.annotation.RequestBody;
19	
20	@Validated
21	public class BuildOwner {
22	
23	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
24	            Out<Boolean> sharesHousehold)
25	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
26	            InvalidPostcodeException, FutureRegistrationDateException {
27	        // Publish the request-only 'sharesHousehold' flag for the household duplicate check.
28	        // Not part of the Owner entity, so it travels as a separate variable.
29	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
30	        // Normalize the address fields up front. The structured 'addressLine1'/'addressLine2' are
31	        // preferred over the flat 'address' when supplied; the composed 'address' is the normalized
32	        // 'addressLine1' with the normalized 'addressLine2' appended (single space) when present, and
33	        // falls back to the normalized flat 'address' otherwise. Composing here means the required
34	        // check below rejects an address that is blank in both forms, and every later comparison sees
35	        // the stored normalized form.
36	        request.setAddressLine1(Addresses.normalizeToNull(request.getAddressLine1()));
37	        request.setAddressLine2(Addresses.normalizeToNull(request.getAddressLine2()));
38	        request.setAddress(Addresses.compose(
39	                request.getAddressLine1(), request.getAddressLine2(), request.getAddress()));
40	        List<String> missing = new ArrayList<>();
41	        if (isBlank(request.getFirstName())) {
42	            missing.add("firstName");
43	        }
44	        if (isBlank(request.getLastName())) {
45	            missing.add("lastName");
46	        }
47	        if (isBlank(request.getAddress())) {
48	            missing.add("address");
49	        }
50	        if (isBlank(request.getCity())) {
51	            missing.add("city");
52	        }
53	        if (isBlank(request.getTelephone())) {
54	            missing.add("telephone");
55	        }
56	        if (!missing.isEmpty()) {
57	            throw new MissingOwnerFieldsException(missing);
58	        }
59	        // Normalize the telephone to E.164 form (keep '+'/country code, else assume '+61').
60	        request.setTelephone(Telephones.toE164(request.getTelephone()));
61	        // Email is optional; when present it must be syntactically valid and is stored lower-cased.
62	        request.setEmail(OwnerEmails.normalize(request.getEmail()));
63	        // Postcode is optional; when present it must be valid for the city's region
64	        // (a city with no known region accepts any 4-digit postcode). The 4-digit shape
65	        // is enforced by the request schema, so only the region range is checked here.
66	        Postcodes.validate(request.getCity(), request.getPostcode());
67	        Owner owner = ownerMapper.toOwner(request);
68	        // The effective registration date is the supplied value, or the server's current date when
69	        // none is supplied. Either way it must fall on a business day: a Saturday or Sunday rolls
70	        // forward to the next Monday. Everything derived from the registration date (membership
71	        // number year, daily create-limit) then sees this adjusted business day.
72	        LocalDate registrationDate = owner.getRegistrationDate();
73	        if (registrationDate == null) {
74	            registrationDate = LocalDate.now();
75	        } else if (registrationDate.isAfter(LocalDate.now())) {
76	            // A supplied registration date may not be in the future.
77	            throw new FutureRegistrationDateException(
78	                    "registrationDate " + registrationDate + " is later than the server date");
79	        }
80	        owner.setRegistrationDate(toBusinessDay(registrationDate));
81	        built.set(owner);
82	    }
83	
84	    /** Roll a weekend date forward to the next Monday; business days are returned unchanged. */
85	    private static LocalDate toBusinessDay(LocalDate date) {
86	        return switch (date.getDayOfWeek()) {
87	            case SATURDAY -> date.plusDays(2);
88	            case SUNDAY -> date.plusDays(1);
89	            default -> date;
90	        };
91	    }
92	
93	    private static boolean isBlank(String value) {
94	        return value == null || value.isBlank();
95	    }
96	}
