1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
7	
8	public class ApplyOwner {
9	
10	    public void service(@Val Owner owner, @Val OwnerFieldsDto request) throws InvalidPostcodeException {
11	        // Postcode is optional; when present it must be valid for the city's region.
12	        Postcodes.validate(request.getCity(), request.getPostcode());
13	        // Prefer the structured address fields when present, falling back to the flat 'address';
14	        // both the individual lines and the composed 'address' are stored normalized.
15	        String addressLine1 = Addresses.normalizeToNull(request.getAddressLine1());
16	        String addressLine2 = Addresses.normalizeToNull(request.getAddressLine2());
17	        owner.setAddressLine1(addressLine1);
18	        owner.setAddressLine2(addressLine2);
19	        owner.setAddress(Addresses.compose(addressLine1, addressLine2, request.getAddress()));
20	        owner.setCity(request.getCity());
21	        owner.setFirstName(request.getFirstName());
22	        owner.setLastName(request.getLastName());
23	        owner.setTelephone(request.getTelephone());
24	        owner.setEmail(request.getEmail());
25	        owner.setPostcode(request.getPostcode());
26	    }
27	}
