70	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
71	                .membershipLevel(membershipPoints(owner));
72	    }
73	
74	    /**
75	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
76	     * present (non-null and non-blank), otherwise {@code PHONE}.
77	     */
78	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
79	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
80	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
81	    }
82	
83	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
84	    private static final int ADULT_AGE = 18;
85	
86	    /** The age (in years) at which an owner becomes a senior. */
87	    private static final int SENIOR_AGE = 65;
88	
89	    /**
90	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
91	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
92	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
93	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
94	     * either the birth date or the registration date is absent, so an owner created
95	     * without a birth date has no age band.
96	     */
97	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
98	        LocalDate birthDate = owner.getBirthDate();
99	        LocalDate registrationDate = owner.getRegistrationDate();
100	        if (birthDate == null || registrationDate == null) {
101	            return null;
102	        }
103	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
104	        if (age < ADULT_AGE) {
105	            return OwnerDto.AgeBandEnum.MINOR;
106	        }
107	        if (age < SENIOR_AGE) {
108	            return OwnerDto.AgeBandEnum.ADULT;
109	        }
110	        return OwnerDto.AgeBandEnum.SENIOR;
111	    }
112	
113	    /**
114	     * Derives the owner's {@code locality} (canonical region string) from the
115	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
116	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
117	     * fall back to deriving the region directly from postcode, then city, then
118	     * {@code "UNKNOWN"}.
119	     */
120	    protected String locality(Owner owner) {
121	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCodes
122	                .regionOf(owner.getCustomerCode());
123	        if (region != null) {
124	            return region;
125	        }
126	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCodes.region(owner);
127	    }
128	
129	    /** Fixed region -> IANA timezone table. */
130	    private static final java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
131	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
132	
133	    /**
134	     * Derives the owner's {@code timezone} (IANA name) from the {@link #locality(Owner)
135	     * locality}/region via the fixed region-to-timezone table (NSW->Australia/Sydney,
136	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns {@code null} when the
137	     * region is not in the table (e.g. an {@code UNKNOWN} locality), so such owners have
138	     * no timezone.
139	     */
140	    protected String timezone(Owner owner) {
141	        return REGION_TIMEZONE.get(locality(owner));
142	    }
143	
144	    /**
145	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
146	     * the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Returns {@code null} when either the
147	     * customer code or the registration date is absent (e.g. legacy seed owners).
148	     */
149	    protected String membershipNumber(Owner owner) {
150	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
151	            return null;
152	        }
153	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
154	    }
155	
156	    /**
157	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
158	     * been created for this owner's {@code registrationDate}, using the same per-day
159	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
160	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
161	     */
162	    protected boolean bulkSignupWarning(Owner owner) {
163	        LocalDate registrationDate = owner.getRegistrationDate();
164	        if (registrationDate == null) {
165	            return false;
166	        }
167	        long count = ownerRepository.findAll().stream()
168	                .filter(existing -> !existing.getId().equals(owner.getId()))
169	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
170	                .count();
171	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
172	    }
173	
174	    /**
175	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
176	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
177	     * legacy seed owners).
178	     */
179	    protected Integer checkDigit(Owner owner) {
180	        String customerCode = owner.getCustomerCode();
181	        if (customerCode == null) {
182	            return null;
183	        }
184	        int sum = 0;
185	        boolean dbl = true;
186	        for (int i = customerCode.length() - 1; i >= 0; i--) {
187	            char c = customerCode.charAt(i);
188	            if (c < '0' || c > '9') {
189	                continue;
190	            }
191	            int d = c - '0';
192	            if (dbl) {
193	                d *= 2;
194	                if (d > 9) {
195	                    d -= 9;
196	                }
197	            }
198	            sum += d;
199	            dbl = !dbl;
200	        }
201	        return (10 - (sum % 10)) % 10;
202	    }
203	
204	    /**
205	     * The owner's {@code salutation}: the {@code title} followed by a single space and the last
206	     * name when a title is supplied (non-null and non-blank), otherwise just the last name.
207	     */
208	    protected String salutation(Owner owner) {
209	        String title = owner.getTitle();
210	        if (title == null || title.isBlank()) {
211	            return owner.getLastName();
212	        }
213	        return title + " " + owner.getLastName();
214	    }
215	
216	    public abstract Owner toOwner(OwnerDto ownerDto);
217	
218	    @Mapping(target = "id", ignore = true)
219	    @Mapping(target = "pets", ignore = true)
220	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
221	
222	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
223	
224	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
225	
226	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
227	        OwnerPageDto ownerPageDto = new OwnerPageDto();
228	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
229	        ownerPageDto.setPage(ownerPage.getNumber());
230	        ownerPageDto.setSize(ownerPage.getSize());
231	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
232	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
233	        return ownerPageDto;
234	    }
235	}
